#include <iostream>
#include <memory>
#include <string>

class Resource {
public:
    explicit Resource(int id) : id_(id) {
        std::cout << "Resource " << id_ << " acquired\n";
    }
    ~Resource() {
        std::cout << "Resource " << id_ << " destroyed\n";
    }
    void display() const {
        std::cout << "Resource value: " << id_ << "\n";
    }
private:
    int id_;
};

int main() {
    // Single object management with unique_ptr
    std::cout << "--- Single Resource ---\n";
    {
        auto resPtr = std::make_unique<Resource>(42);
        resPtr->display();
        (*resPtr).display();
    } // resPtr automatically destroyed here

    // Array management with unique_ptr
    std::cout << "\n--- Dynamic Array ---\n";
    {
        auto strArray = std::make_unique<std::string[]>(3);
        strArray[0] = "Alpha";
        strArray[1] = "Beta";
        strArray[2] = "Gamma";
        for (int i = 0; i < 3; ++i) {
            std::cout << "strArray[" << i << "] = " << strArray[i] << "\n";
        }
    } // strArray destroyed with delete[] here

    return 0;
}

#include <iostream>
#include <stdexcept>
#include <string>

void validateAge(int age) {
    if (age < 0) {
        throw std::invalid_argument("Age cannot be negative");
    }
    if (age > 150) {
        throw std::out_of_range("Age exceeds maximum human limit");
    }
}

void intermediateWorker(int age) {
    try {
        validateAge(age);
    } catch (...) {
        std::cout << "Worker logged exception; rethrowing...\n";
        throw; // rethrow current active exception
    }
}

int main() {
    int testAges[] = {-5, 200};

    for (int age : testAges) {
        try {
            intermediateWorker(age);
        } catch (const std::out_of_range& ex) {
            std::cout << "Specific out_of_range caught: " << ex.what() << "\n";
        } catch (const std::logic_error& ex) {
            std::cout << "General logic_error caught: " << ex.what() << "\n";
        } catch (const std::exception& ex) {
            std::cout << "Base std::exception caught: " << ex.what() << "\n";
        } catch (...) {
            std::cout << "Unknown non-standard exception caught\n";
        }
    }
    return 0;
}
